# HISTORY tab (1.1.0): forensics.alarmHistory.rows(filter, hours, mode, search) - read only while the tab is open,
# then every 15 s and on every chip or search change. 30 days kept (shared.purge).
if str(value.tab or '') != 'history':
	return {'rows': [], 'info': '', 'infoColor': '#5F696B'}
try:
	return forensics.alarmHistory.rows(value.f, value.h, value.m, value.s)
except:
	return {'rows': [], 'info': 'the history needs forensics.alarmHistory 1.0.0', 'infoColor': '#C02026'}
